insert into public.careers (slug, name, description, responsibilities, prerequisites, suggested_projects, sort_order) values ('software-developer', 'Software Developer', 'Designs, builds, tests and maintains software applications, turning requirements into reliable, readable code.', array['Implement features from requirements and user stories', 'Write automated tests and fix defects', 'Review teammates'' code and keep the codebase maintainable', 'Design data models and integrate with APIs and databases', 'Collaborate through version control and code review workflows']::text[], array['Comfort with at least one programming language', 'Basic logical and mathematical reasoning', 'Familiarity with using a command line']::text[], '[{"title":"Task tracker API with tests","description":"Build a small REST API (create, list, update, delete tasks) backed by a SQL database, with automated tests and a README describing endpoints."},{"title":"CLI utility","description":"Write a command-line tool that parses a log or CSV file and reports summary statistics, with unit tests for the parsing logic."},{"title":"Contribute to open source","description":"Find a beginner-friendly issue in an open-source project, submit a pull request and respond to review feedback."}]'::jsonb, 1)
