insert into public.careers (slug, name, description, responsibilities, prerequisites, suggested_projects, sort_order) values ('cybersecurity-engineer', 'Cybersecurity Engineer', 'Protects systems, networks and data by monitoring for threats, finding weaknesses before attackers do and responding to incidents.', array['Monitor security alerts and investigate suspicious activity', 'Assess systems for vulnerabilities and recommend remediation', 'Harden servers, networks and web applications', 'Respond to and document security incidents', 'Automate security checks with scripts']::text[], array['Understanding of how computers and operating systems work', 'Basic networking concepts (IP addresses, ports)', 'Willingness to work only in authorized lab environments']::text[], '[{"title":"Home security lab report","description":"Build an isolated virtual lab, collect logs from a Linux host, write two detection rules for suspicious activity and document an investigation of a simulated alert."},{"title":"Log analysis script","description":"Write a Python script that parses SSH authentication logs and flags brute-force patterns, with a short report of findings."},{"title":"Web app hardening review","description":"Review a deliberately vulnerable training app (e.g. OWASP Juice Shop) locally, document three vulnerability classes found and the fixes you would apply."}]'::jsonb, 2)
