insert into public.careers (slug, name, description, responsibilities, prerequisites, suggested_projects, sort_order) values ('data-analyst', 'Data Analyst', 'Turns raw data into answers: cleans and queries datasets, analyses trends and communicates findings that inform decisions.', array['Query and combine data from databases and spreadsheets', 'Clean and validate datasets before analysis', 'Apply descriptive and inferential statistics', 'Build dashboards and visualizations for stakeholders', 'Present findings and recommendations clearly']::text[], array['Comfort with school-level mathematics', 'Experience using spreadsheets', 'Curiosity about how businesses measure success']::text[], '[{"title":"Public dataset analysis","description":"Pick an open dataset, clean it, answer three business questions with SQL or pandas and present the results in a short slide-style report."},{"title":"KPI dashboard","description":"Build an interactive dashboard tracking five KPIs from a sample sales dataset, with filters and a one-paragraph insight for each chart."},{"title":"A/B test write-up","description":"Analyse a sample A/B test dataset, check statistical significance and recommend a decision with caveats."}]'::jsonb, 3)
