insert into public.careers (slug, name, description, responsibilities, prerequisites, suggested_projects, sort_order) values ('ai-ml-engineer', 'AI/ML Engineer', 'Builds, evaluates and deploys machine learning models, from data preparation to monitoring models in production.', array['Prepare and engineer features from raw data', 'Train, tune and evaluate machine learning models', 'Build deep learning models for unstructured data', 'Package and deploy models behind reliable services', 'Monitor model performance and data drift']::text[], array['Solid programming fundamentals, ideally in Python', 'High-school algebra and basic probability', 'Comfort reading technical documentation']::text[], '[{"title":"End-to-end ML pipeline","description":"Train a classification model on a public dataset, compare it with a baseline, track experiments and serve predictions through a small API."},{"title":"Image classifier","description":"Fine-tune a small pretrained neural network on an image dataset and report accuracy, a confusion matrix and failure cases."},{"title":"Model card","description":"Write a model card for one of your models covering intended use, metrics, limitations and fairness checks."}]'::jsonb, 4)
