insert into public.careers (slug, name, description, responsibilities, prerequisites, suggested_projects, sort_order) values ('web-developer', 'Web Developer', 'Builds fast, accessible and secure websites and web applications across the front end and back end.', array['Build responsive, accessible user interfaces', 'Implement interactive features with JavaScript and React', 'Create server-side APIs and connect databases', 'Optimize performance and fix cross-browser issues', 'Apply secure coding practices']::text[], array['Basic computer literacy and comfort with a code editor', 'Interest in design and user experience', 'Logical problem-solving skills']::text[], '[{"title":"Full-stack notes app","description":"Build a notes app with a React front end, a Node.js API and a database, including form validation and an accessibility check."},{"title":"Portfolio site","description":"Create a responsive personal portfolio that scores well on a Lighthouse audit for performance and accessibility."},{"title":"Public API dashboard","description":"Fetch data from a public API and display it with loading, error and empty states in a typed React application."}]'::jsonb, 5)
